// Validate incoming document upload event
const body = $input.item.json.body;
const headers = $input.item.json.headers;

if (!headers.authorization) {
  throw new Error('Missing Authorization header');
}

if (!body.file_id || !body.org_id || !body.thread_id) {
  throw new Error('Missing required fields: file_id, org_id, thread_id');
}

return {
  json: {
    file_id: body.file_id,
    org_id: body.org_id,
    thread_id: body.thread_id,
    filename: body.filename,
    file_path: body.file_path,
    mime_type: body.mime_type,
    file_size: body.file_size
  }
};

// Calculate file hash (simulated - in production use actual file reading)
const fileData = $('Validate Input').item.json;
const existingData = $input.item.json;

// Simulate hash calculation
// In production: read file from file_path and calculate SHA256
const crypto = require('crypto');
const hash = crypto.createHash('sha256')
  .update(fileData.filename + fileData.file_size + Date.now())
  .digest('hex');

return {
  json: {
    ...fileData,
    calculated_hash: hash,
    existing_hash: existingData.file_hash || null,
    is_new: !existingData.file_hash || existingData.file_hash !== hash
  }
};

// Skip processing - file already processed
const data = $input.item.json;

return {
  json: {
    file_id: data.file_id,
    status: 'skipped',
    reason: 'File already processed (hash match)',
    hash: data.existing_hash
  }
};

// Detect document type and validate readability
const data = $input.item.json;

const mimeType = data.mime_type || '';
let documentType = 'unknown';
let category = 'Outros';
let needsOCR = false;

// Categorize by mime type
if (mimeType.includes('pdf')) {
  documentType = 'pdf';
  category = 'Documentos';
  needsOCR = false; // Assume PDF is text-based
} else if (mimeType.includes('image')) {
  documentType = 'image';
  category = 'Imagens/Plantas';
  needsOCR = true;
} else if (mimeType.includes('word') || mimeType.includes('document')) {
  documentType = 'document';
  category = 'Documentos';
} else if (mimeType.includes('spreadsheet') || mimeType.includes('excel')) {
  documentType = 'spreadsheet';
  category = 'Planilhas';
}

// Refine category based on filename
const filename = (data.filename || '').toLowerCase();
if (filename.includes('boleto') || filename.includes('pagamento')) {
  category = 'Comprovantes/Boletos';
} else if (filename.includes('licença') || filename.includes('licenca') || filename.includes('alvara')) {
  category = 'Licenças Anteriores';
} else if (filename.includes('projeto') || filename.includes('planta')) {
  category = 'Projetos Arquitetônicos';
} else if (filename.includes('empreendedor') || filename.includes('cpf') || filename.includes('cnpj')) {
  category = 'Documentos do Empreendedor';
}

return {
  json: {
    ...data,
    document_type: documentType,
    category: category,
    needs_ocr: needsOCR,
    readable: true // Assume readable by default
  }
};

// Extract metadata from document
const data = $input.item.json;

// Simulate metadata extraction
// In production: use PDF parser, image EXIF, etc.
const metadata = {
  extracted_date: new Date().toISOString(),
  page_count: 1,
  language: 'pt-BR',
  has_text: !data.needs_ocr,
  confidence: 0.95
};

// Try to extract date from filename
const dateMatch = data.filename.match(/(\d{2}[-/]\d{2}[-/]\d{4})|(\d{4}[-/]\d{2}[-/]\d{2})/);
if (dateMatch) {
  metadata.document_date = dateMatch[0];
}

return {
  json: {
    ...data,
    metadata: metadata
  }
};

// Store OCR result
const data = $('Extract Metadata').item.json;
const ocrResult = $input.item.json.response || $input.item.json.text || '';

data.extracted_text = ocrResult;
data.metadata.ocr_performed = true;

return { json: data };

// Prepare vector data for storage
const data = $('Merge OCR Path').item.json;
const embedding = $input.item.json.embedding || [];

return {
  json: {
    file_id: data.file_id,
    org_id: data.org_id,
    thread_id: data.thread_id,
    embedding: JSON.stringify(embedding),
    text_content: data.extracted_text || '',
    metadata: data.metadata
  }
};

// Build success response
const data = $('Prepare Vector Data').item.json;
const fileData = $('Detect Document Type').item.json;

return {
  json: {
    status: 'success',
    file_id: data.file_id,
    category: fileData.category,
    hash: $('Calculate Hash').item.json.calculated_hash,
    vectorized: true,
    message: 'Document processed and classified successfully'
  }
};
